    private void btnclearActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnclearActionPerformed
        Txtstart.setText("");
        TxtEnd.setText("");
        TxtTotal.setText("");
        Txtstart.requestFocusInWindow();
    }//GEN-LAST:event_btnclearActionPerformed

    private void btncalculateActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btncalculateActionPerformed
        TxtTotal.setText("");
        if (Txtstart.getText().trim().isEmpty() || TxtEnd.getText().trim().isEmpty()) {
            JOptionPane.showMessageDialog(this, "Please enter both start and end times.");
            return;
        }
        try {
            int start = Integer.parseInt(Txtstart.getText().trim());
            int end = Integer.parseInt(TxtEnd.getText().trim());
            if (start < 0 || start > 23 || end < 1 || end > 24 || end <= start) {
                JOptionPane.showMessageDialog(this, "Use start 0–23 and end 1–24. End must be greater than start.");
                return;
            }
            int hours = end - start;
            int total = hours * 500;
            TxtTotal.setText(total + " RWF (" + hours + " hours)");
        } catch (NumberFormatException ex) {
            JOptionPane.showMessageDialog(this, "Enter whole numbers only.");
        }
    }//GEN-LAST:event_btncalculateActionPerformed

